// The owner's signing key and everything derived from it, as +PLUS's Kotlin core does (OwnerKey, BackupCodec,
// AvbKey, OwnerCert, BuildManifest). The phone re-derives the same values from the backup it imports, so every byte
// must match: test/vectors.json is generated by the Kotlin code and checked by test/owner.test.mjs.
// A key is { p, q, n, e, d, dp, dq, qi } as BigInts. Uses only Web Crypto, so it runs in the page and in Node.

import { crc32 } from "./zip.js";

const E = 65537n;
const PRIME_LEN = 256;
const PREFIX = "PLUSKEY1";
const PAYLOAD_LEN = 1 + 2 * PRIME_LEN + 8 + 4;
const TEXT_LEN = (PAYLOAD_LEN * 8) / 5;
const ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";

export class BackupError extends Error {
  /** reason: PREFIX, LENGTH, CHARSET, VERSION, CRC or FINGERPRINT (as Kotlin's BackupFormatException). */
  constructor(reason, message) {
    super(message);
    this.reason = reason;
  }
}

// ---- BigInt helpers

function modPow(b, x, m) {
  let r = 1n;
  b %= m;
  for (; x > 0n; x >>= 1n, b = (b * b) % m) if (x & 1n) r = (r * b) % m;
  return r;
}
function modInv(a, m) {
  let [r0, r1, s0, s1] = [((a % m) + m) % m, m, 1n, 0n];
  while (r1 !== 0n) {
    const q = r0 / r1;
    [r0, r1, s0, s1] = [r1, r0 - q * r1, s1, s0 - q * s1];
  }
  if (r0 !== 1n) throw new Error("not invertible");
  return ((s0 % m) + m) % m;
}
const bitLength = (v) => v.toString(2).length;
function toBytes(v, len) {
  const hex = v.toString(16).padStart(len * 2, "0");
  if (hex.length > len * 2) throw new Error(`value does not fit in ${len} bytes`);
  return Uint8Array.from({ length: len }, (_, i) => parseInt(hex.substr(i * 2, 2), 16));
}
const minBytes = (v) => toBytes(v, Math.max(1, Math.ceil(v.toString(16).length / 2)));
const fromBytes = (b) => BigInt("0x" + (Array.from(b, (x) => x.toString(16).padStart(2, "0")).join("") || "0"));
const concat = (...parts) => {
  const out = new Uint8Array(parts.reduce((n, p) => n + p.length, 0));
  let o = 0;
  for (const p of parts) { out.set(p, o); o += p.length; }
  return out;
};
const hex = (b) => Array.from(b, (x) => x.toString(16).padStart(2, "0")).join("");
const sha256 = async (b) => new Uint8Array(await crypto.subtle.digest("SHA-256", b));
const b64 = (b) => btoa(String.fromCharCode(...b));
const b64url = (b) => b64(b).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
const fromB64url = (s) => Uint8Array.from(atob(s.replace(/-/g, "+").replace(/_/g, "/")), (c) => c.charCodeAt(0));

// ---- The key

export function keyFromPrimes(p, q) {
  if (p === q) throw new Error("p and q must differ");
  const n = p * q;
  const d = modInv(E, (p - 1n) * (q - 1n));
  return { p, q, n, e: E, d, dp: d % (p - 1n), dq: d % (q - 1n), qi: modInv(q, p) };
}

/** A new RSA-4096 owner key from the browser's own generator (Web Crypto). */
export async function generateOwnerKey() {
  const pair = await crypto.subtle.generateKey(
    { name: "RSASSA-PKCS1-v1_5", modulusLength: 4096, publicExponent: new Uint8Array([1, 0, 1]), hash: "SHA-256" },
    true, ["sign", "verify"]);
  const jwk = await crypto.subtle.exportKey("jwk", pair.privateKey);
  return keyFromPrimes(fromBytes(fromB64url(jwk.p)), fromBytes(fromB64url(jwk.q)));
}

// ---- AVB public key blob (libavb AvbRSAPublicKeyHeader + n + rr) and fingerprint

export function avbPkmd(k) {
  const bits = bitLength(k.n);
  if (bits % 32 !== 0) throw new Error("modulus size must be a multiple of 32 bits");
  const len = bits / 8;
  const two32 = 1n << 32n;
  const n0inv = two32 - modInv(k.n % two32, two32);
  const rr = modPow(1n << BigInt(bits), 2n, k.n);
  return concat(toBytes(BigInt(bits), 4), toBytes(n0inv % two32, 4), toBytes(k.n, len), toBytes(rr, len));
}

const fingerprint = async (k) => (await sha256(avbPkmd(k))).slice(0, 8);
export const fingerprintHex = async (k) => hex(await fingerprint(k));

/** As shown to the owner: 16 hex digits in groups of four. */
export const fingerprintDisplay = async (k) => (await fingerprintHex(k)).toUpperCase().match(/.{4}/g).join(" ");

// ---- Backup text and QR string: PLUSKEY1 + base32(0x01 ‖ p ‖ q ‖ fingerprint ‖ CRC-32)

async function payload(k) {
  const body = concat(new Uint8Array([1]), toBytes(k.p, PRIME_LEN), toBytes(k.q, PRIME_LEN), await fingerprint(k));
  return concat(body, toBytes(BigInt(crc32(body)), 4));
}
function base32(data) {
  let s = "", buf = 0, bits = 0;
  for (const x of data) {
    buf = ((buf << 8) | x) & 0xffff;
    bits += 8;
    while (bits >= 5) { s += ALPHABET[(buf >> (bits - 5)) & 31]; bits -= 5; }
  }
  if (bits > 0) s += ALPHABET[(buf << (5 - bits)) & 31];
  return s;
}
function unbase32(text) {
  const out = [];
  let buf = 0, bits = 0;
  for (const c of text) {
    const v = ALPHABET.indexOf(c);
    if (v < 0) throw new BackupError("CHARSET", `'${c}' is not a backup character`);
    buf = ((buf << 5) | v) & 0xffff;
    bits += 5;
    if (bits >= 8) { out.push((buf >> (bits - 8)) & 0xff); bits -= 8; }
  }
  return Uint8Array.from(out);
}

/** For the password manager: PLUSKEY1-XXXXX-XXXXX-… */
export const encodeBackup = async (k) => `${PREFIX}-` + base32(await payload(k)).match(/.{1,5}/g).join("-");
/** For the QR code: the same characters without separators. */
export const qrPayload = async (k) => PREFIX + base32(await payload(k));

/** Accepts either form, any case, with spaces and dashes anywhere. */
export async function decodeBackup(text) {
  const clean = text.replace(/[\s-]/g, "").toUpperCase();
  if (!clean.startsWith(PREFIX)) throw new BackupError("PREFIX", `the text must start with ${PREFIX}`);
  const body = clean.slice(PREFIX.length);
  if (body.length !== TEXT_LEN) throw new BackupError("LENGTH", `expected ${TEXT_LEN} characters, got ${body.length}`);
  const bytes = unbase32(body);
  const crc = Number(fromBytes(bytes.slice(PAYLOAD_LEN - 4)));
  if (crc !== crc32(bytes.slice(0, PAYLOAD_LEN - 4))) throw new BackupError("CRC", "a character is wrong");
  if (bytes[0] !== 1) throw new BackupError("VERSION", `unknown backup version ${bytes[0]}`);
  let key;
  try {
    key = keyFromPrimes(fromBytes(bytes.slice(1, 1 + PRIME_LEN)), fromBytes(bytes.slice(1 + PRIME_LEN, 1 + 2 * PRIME_LEN)));
  } catch {
    throw new BackupError("FINGERPRINT", "the key material is invalid");
  }
  const fp = bytes.slice(1 + 2 * PRIME_LEN, 1 + 2 * PRIME_LEN + 8);
  if (hex(fp) !== (await fingerprintHex(key))) throw new BackupError("FINGERPRINT", "the key does not match its fingerprint");
  return key;
}

// ---- DER (definite lengths up to 3 bytes, as Kotlin's Der)

function tlv(tag, body) {
  const l = body.length;
  const len = l < 0x80 ? [l] : l < 0x100 ? [0x81, l] : l < 0x10000 ? [0x82, l >> 8, l & 0xff]
    : [0x83, l >> 16, (l >> 8) & 0xff, l & 0xff];
  return concat(new Uint8Array([tag, ...len]), body);
}
const seq = (...parts) => tlv(0x30, concat(...parts));
const oid = (h) => tlv(0x06, Uint8Array.from(h.match(/../g), (x) => parseInt(x, 16)));
const derInt = (v) => {
  const b = minBytes(v);
  return tlv(0x02, b[0] & 0x80 ? concat(new Uint8Array([0]), b) : b);
};
const NULL = tlv(0x05, new Uint8Array(0));
const RSA_ENCRYPTION = seq(oid("2a864886f70d010101"), NULL);
const SHA256_WITH_RSA = seq(oid("2a864886f70d01010b"), NULL);
const text = (s) => new TextEncoder().encode(s);
const NAME = seq(tlv(0x31, seq(oid("550403"), tlv(0x0c, text("+PLUS owner")))));
const VALIDITY = seq(tlv(0x17, text("250101000000Z")), tlv(0x17, text("491231235959Z")));

/** SubjectPublicKeyInfo, as Java's RSAPublicKey.getEncoded(). */
export const spki = (k) => seq(RSA_ENCRYPTION, tlv(0x03, concat(new Uint8Array([0]), seq(derInt(k.n), derInt(k.e)))));

function pem(label, der) {
  return `-----BEGIN ${label}-----\n` + b64(der).match(/.{1,64}/g).join("\n") + `\n-----END ${label}-----\n`;
}

/** Unencrypted PKCS#8, for avbroot inside the page. It stays in memory; it is never written to browser storage. */
export function privateKeyPem(k) {
  const rsa = seq(derInt(0n), ...[k.n, k.e, k.d, k.p, k.q, k.dp, k.dq, k.qi].map(derInt));
  return pem("PRIVATE KEY", seq(derInt(0n), RSA_ENCRYPTION, tlv(0x04, rsa)));
}

async function signingKey(k) {
  const j = (v) => b64url(minBytes(v));
  const jwk = { kty: "RSA", n: j(k.n), e: j(k.e), d: j(k.d), p: j(k.p), q: j(k.q), dp: j(k.dp), dq: j(k.dq), qi: j(k.qi), ext: true };
  return crypto.subtle.importKey("jwk", jwk, { name: "RSASSA-PKCS1-v1_5", hash: "SHA-256" }, false, ["sign"]);
}

/** The owner's OTA certificate (Kotlin OwnerCert.derive): deterministic, so the phone derives the same bytes. */
export async function ownerCertPem(k) {
  const tbs = seq(tlv(0x02, new Uint8Array([1])), SHA256_WITH_RSA, NAME, VALIDITY, NAME, spki(k));
  const sig = new Uint8Array(await crypto.subtle.sign("RSASSA-PKCS1-v1_5", await signingKey(k), tbs));
  return pem("CERTIFICATE", seq(tbs, SHA256_WITH_RSA, tlv(0x03, concat(new Uint8Array([0]), sig))));
}

// ---- Build manifest (/product/etc/plus/build-manifest.json), formatted as kotlinx.serialization prettyPrint

export function manifestJson({ device, grapheneos, ownerKeyFingerprint, installer }) {
  return JSON.stringify({
    format: 1,
    device,
    grapheneos: { build: grapheneos.build, ota_sha256: grapheneos.otaSha256 },
    owner_key_fingerprint: ownerKeyFingerprint,
    installer: { version: installer.version, apk_sha256: installer.apkSha256 },
    addons: [],
  }, null, 4);
}
